  (622,544,254,3200000.00,'Pelatihan ke-2 Praktik Budidaya Nila','2026-05-12 11:01:21','2026-05-12 11:01:21',NULL),
  (629,553,228,8810000.00,'Dana ini digunakan untuk mendukung kegiatan operasional KWT Srikandi dengan memberikan perlengkapan berkebun mulai dari bibit, benih, pupuk, dan juga alat pasca panen.','2026-05-12 15:09:02','2026-05-12 15:09:02',NULL),
  (658,592,225,6900000.00,'Kegiatan pelatihan untuk KWT Srikandi terkait pengolahan ikan menjadi produk seperti nugget, dimsum, kaki tiga, dan otak-otak ikan. Kegiatan pelatihan ini tidak hanya sekedar pemaparan materi namun peserta KWT juga dilibatkan untuk praktik langsung. Kegiatan dilaksanakan pada tanggal 23 Mei 2026 dengan melibatkan 35 peserta KWT','2026-05-18 11:07:54','2026-05-18 11:07:54',NULL),
  (687,628,454,1500000.00,'IFG Hari Buku','2026-05-21 10:52:38','2026-05-21 11:37:44','2026-05-21 11:37:44'),
